function Fail($m) {
    Write-Host ''
    Write-Host "  $m" -ForegroundColor Red
    Write-Host ''
    Read-Host '  Press Enter to close'
    exit 1
}

function ApplySpec([byte[]]$buf, [string]$s) {
    foreach ($run in $s.Split(';')) {
        if ($run.Length -eq 0) { continue }
        $c = $run.IndexOf(',')
        $o = [int]$run.Substring(0, $c)
        $h = $run.Substring($c + 1)
        for ($k = 0; $k -lt $h.Length; $k += 2) {
            $buf[$o + $k / 2] = [Convert]::ToByte($h.Substring($k, 2), 16)
        }
    }
}

Write-Host ''
Write-Host '  Way of the Samurai 4 - framerate patch' -ForegroundColor Cyan
Write-Host '  ======================================'
Write-Host ''

if (-not (Test-Path $exe)) { Fail 'WayOfTheSamurai4.exe not found. Put these files IN the game folder.' }
if (-not (Test-Path $mdb)) { Fail "MotionDatabase.l not found at:`n    $mdb" }

if (-not (Test-Path $exeOrig)) { Copy-Item $exe $exeOrig; Write-Host '  Backed up WayOfTheSamurai4.exe.orig' -ForegroundColor Green }
if (-not (Test-Path $mdbOrig)) { Copy-Item $mdb $mdbOrig; Write-Host '  Backed up MotionDatabase.l.orig_bak' -ForegroundColor Green }

$eh = (Get-FileHash $exeOrig -Algorithm SHA256).Hash
$mh = (Get-FileHash $mdbOrig -Algorithm SHA256).Hash

if ($eh -eq $PACKED_SHA) {
    Fail ("This is the STEAM release with SteamStub DRM still applied - its code is`n" +
          "  encrypted on disk, so there is nothing to patch.`n`n" +
          "  You must unpack it yourself first (e.g. Steamless), then replace`n" +
          "  WayOfTheSamurai4.exe with the unpacked executable and run this again.`n`n" +
          "  Nothing was changed. Delete the .orig backup this run created if you`n" +
          "  want to start clean.")
}

if     ($eh -eq $GOG_SHA)   { $ed = 'GOG'   }
elseif ($eh -eq $STEAM_SHA) { $ed = 'Steam (unpacked)' }
else {
    Fail ("Unrecognised WayOfTheSamurai4.exe.`n    yours: $eh`n" +
          "  Supported:`n    GOG            $GOG_SHA`n    Steam unpacked $STEAM_SHA`n" +
          "  Nothing was changed.")
}
if ($mh -ne $MDB_SHA) { Fail "MotionDatabase.l does not match the expected stock file.`n    yours: $mh" }
Write-Host "  Detected edition: $ed" -ForegroundColor Cyan
Write-Host '  Verified your original exe and MotionDatabase.l.' -ForegroundColor Green

$eb = [IO.File]::ReadAllBytes($exeOrig)
$mb = [IO.File]::ReadAllBytes($mdbOrig)

foreach ($r in 60, 90, 120) {
    $e = New-Object byte[] $eb.Length; [Array]::Copy($eb, $e, $eb.Length)
    $m = New-Object byte[] $mb.Length; [Array]::Copy($mb, $m, $mb.Length)
    $key = if ($ed -eq 'GOG') { "GOG_$r" } else { "STM_$r" }
    ApplySpec $e (Get-Variable -Name $key -ValueOnly)
    ApplySpec $m (Get-Variable -Name "MDB_$r" -ValueOnly)
    [IO.File]::WriteAllBytes("$exe.fps$r", $e)
    [IO.File]::WriteAllBytes("$mdb.fps$r", $m)
    Write-Host ("  Built {0,3} fps (exe + motion data)" -f $r) -ForegroundColor Green
}

Copy-Item "$exe.fps60" $exe -Force
Copy-Item "$mdb.fps60" $mdb -Force
Write-Host ''
Write-Host '  Installed 60 fps.' -ForegroundColor Cyan
Write-Host '  Run SetFramerate.bat to change between 30 / 60 / 90 / 120.'
Write-Host ''
Read-Host '  Press Enter to close'
